#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *end;
    long long base = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long long exp = strtoll(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long long mod = strtoll(argv[3], &end, 10);
    if (end == argv[3] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    // modular exponentiation (fast power)
    long long result = 1 % mod;
    long long b = base % mod;
    if (b < 0) b += mod;
    while (exp > 0) {
        if (exp & 1LL) {
            __int128 tmp = ( (__int128) result * b ) % mod;
            result = (long long) tmp;
        }
        exp >>= 1LL;
        if (exp) {
            __int128 tmp = ( (__int128) b * b ) % mod;
            b = (long long) tmp;
        }
    }
    printf("result=%lld\n", result);
    return 0;
}
